let fuzzClosure = {
extension AttributeClauseFileSyntax: SyntaxParseable {
  public static func parse(from parser: inout Parser) -> Self {
    switch self.tokenKind {
    case .poundAvailable:
      return self./*c*/with(\.tokenKind, .poundAvailable)
    }
  }
}
}
